:root {
  --bg: #050b12;
  --panel: rgba(13, 22, 30, 0.8);
  --panel-strong: rgba(17, 27, 36, 0.9);
  --line: rgba(165, 196, 214, 0.28);
  --text: #ebf5ff;
  --muted: #9ab7c7;
  --accent: #76e0ff;
  --warning: #ffbf70;
  --danger: #ff7575;
  --good: #85f0a4;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  background: radial-gradient(circle at top, #0d1620 0%, #03070d 58%, #010305 100%);
  color: var(--text);
  font-family: Arial, Helvetica, sans-serif;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 16px;
}

.game-shell {
  width: min(1200px, 100%);
  min-height: min(900px, 100vh - 32px);
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: rgba(7, 12, 18, 0.74);
  box-shadow: 0 25px 50px rgba(0,0,0,0.45);
}

.hud {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 14px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 14px;
  margin-bottom: 12px;
}

.hud-group {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 110px;
}

.stat span {
  font-size: 10px;
  letter-spacing: 0.12em;
  color: var(--muted);
}

.stat strong {
  font-size: 18px;
}

.game-panel {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 220px;
  gap: 12px;
  align-items: start;
}

canvas {
  width: 100%;
  height: auto;
  display: block;
  border-radius: 16px;
  border: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(17,26,34,1) 0%, rgba(9,16,23,1) 100%);
  box-shadow: inset 0 0 30px rgba(0,0,0,0.35);
}

.message-box {
  grid-column: 1 / -1;
  min-height: 54px;
  background: rgba(3,8,11,0.66);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 12px 14px;
  color: var(--text);
  font-size: 15px;
  line-height: 1.5;
}

.side-panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.side-panel section {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 12px 14px;
}

.side-panel h2 {
  margin: 0 0 8px;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--muted);
}

ul {
  margin: 0;
  padding-left: 18px;
  color: var(--text);
  line-height: 1.5;
}

li + li { margin-top: 6px; }

.controls-wrap {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 12px;
}

.touch-pad {
  position: relative;
  width: 180px;
  height: 180px;
  border-radius: 50%;
  background: rgba(14, 31, 38, 0.7);
  border: 1px solid var(--line);
  margin-left: 8px;
}

.move-btn, .action-buttons button {
  border: 1px solid var(--line);
  background: rgba(16, 36, 44, 0.8);
  color: var(--text);
  border-radius: 12px;
  font-weight: 700;
  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
}

.move-btn {
  position: absolute;
  width: 52px;
  height: 52px;
  font-size: 20px;
}

.move-btn.up { left: 64px; top: 10px; }
.move-btn.left { left: 10px; top: 64px; }
.move-btn.down { left: 64px; top: 118px; }
.move-btn.right { left: 118px; top: 64px; }

.action-buttons {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.action-buttons button {
  min-width: 120px;
  min-height: 52px;
  padding: 10px 18px;
  font-size: 15px;
}

@media (max-width: 880px) {
  .game-shell {
    min-height: 100vh;
    margin: 0;
    border-radius: 0;
    border: none;
    padding: 10px;
  }

  .game-panel {
    grid-template-columns: 1fr;
  }

  .side-panel {
    order: 3;
  }

  .controls-wrap {
    justify-content: center;
    flex-wrap: wrap;
  }

  .action-buttons {
    justify-content: center;
  }
}

@media (max-width: 500px) {
  .hud {
    flex-direction: column;
  }

  .hud-group {
    justify-content: space-between;
  }

  .touch-pad {
    width: 150px;
    height: 150px;
  }

  .move-btn {
    width: 44px;
    height: 44px;
  }

  .move-btn.up { left: 53px; top: 6px; }
  .move-btn.left { left: 6px; top: 53px; }
  .move-btn.down { left: 53px; top: 100px; }
  .move-btn.right { left: 100px; top: 53px; }

  .action-buttons button {
    min-width: 104px;
    flex: 1 1 30%;
  }
}

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const timeLabel = document.getElementById('timeLabel');
const powerLabel = document.getElementById('powerLabel');
const batteryLabel = document.getElementById('batteryLabel');
const statusLabel = document.getElementById('statusLabel');
const messageBox = document.getElementById('messageBox');
const objectiveList = document.getElementById('objectiveList');
const inventoryList = document.getElementById('inventoryList');
const interactButton = document.getElementById('interactButton');
const cameraButton = document.getElementById('cameraButton');
const flashlightButton = document.getElementById('flashlightButton');

const world = {
  width: 960,
  height: 600,
  time: 22,
  solarPower: 100,
  generator: 75,
  battery: 100,
  flashlightOn: true,
  camerasOpen: false,
  keysFound: 0,
  inventory: ['Flashlight'],
  seenThreat: false,
  gameOver: false,
  winningEnding: null,
  objectives: [
    'Power the station and survive until sunrise.',
    'Find the maintenance key and generator fuel.',
    'Secure the station before 6:00 AM.',
    'Decide whether to flee or stay for the truth.'
  ],
  ambient: {
    fog: 0.55,
    light: 0.8
  }
};

const player = {
  x: 165,
  y: 405,
  radius: 12,
  speed: 120,
  facing: { x: 1, y: 0 },
  holding: null,
  ghosted: false,
  stunned: 0,
};

const stations = {
  fuel: { x: 550, y: 190, w: 44, h: 40, name: 'Generator' },
  register: { x: 255, y: 168, w: 54, h: 42, name: 'Counter' },
  cooler: { x: 390, y: 182, w: 50, h: 50, name: 'Cooler' },
  office: { x: 650, y: 160, w: 70, h: 52, name: 'Office' },
  pump1: { x: 140, y: 115, w: 48, h: 66, name: 'Pump 1' },
  pump2: { x: 200, y: 115, w: 48, h: 66, name: 'Pump 2' },
  pump3: { x: 260, y: 115, w: 48, h: 66, name: 'Pump 3' },
  woods: { x: 740, y: 410, w: 130, h: 120, name: 'Forest edge' },
};

const items = [
  { id: 'battery', x: 330, y: 300, label: 'Battery', description: 'A fresh battery. Useful for your flashlight.', type: 'pickup' },
  { id: 'key', x: 770, y: 240, label: 'Maintenance Key', description: 'A rusty key for the control room.', type: 'pickup' },
  { id: 'fuelCan', x: 420, y: 430, label: 'Fuel Can', description: 'Enough fuel to keep the generator running.', type: 'pickup' },
  { id: 'newspaper', x: 700, y: 410, label: 'Old newspaper', description: 'The paper mentions a missing truck driver.', type: 'story' },
  { id: 'radio', x: 140, y: 260, label: 'Portable radio', description: 'Crackles with whispers from the woods.', type: 'story' },
];

const doors = [
  { x: 480, y: 150, w: 70, h: 30, label: 'Garage Door', id: 'garage' },
  { x: 550, y: 315, w: 60, h: 24, label: 'Back Room', id: 'backRoom' },
  { x: 680, y: 315, w: 70, h: 24, label: 'Exit', id: 'exit' },
];

const customers = [
  { x: 160, y: 260, name: 'Customer', active: true, seen: false },
  { x: 360, y: 470, name: 'Night trucker', active: false, seen: false },
  { x: 830, y: 540, name: 'Watcher', active: false, seen: false },
];

const cameraViews = [
  { name: 'Pump lane', x: 160, y: 60, w: 180, h: 120 },
  { name: 'Truck bay', x: 360, y: 60, w: 180, h: 120 },
  { name: 'Forest road', x: 560, y: 60, w: 180, h: 120 },
];

const keys = {
  ArrowUp: false,
  ArrowDown: false,
  ArrowLeft: false,
  ArrowRight: false,
};

let gameState = {
  activeCamera: null,
  message: 'The station hums in the cold night.',
  currentHint: '',
  nearObject: null,
  objectiveIndex: 0,
  night: 0,
  generatorOn: true,
  generatorFuel: false,
  maintenanceKey: false,
  customerWarning: false,
  officeUnlocked: false,
  endState: null,
};

const clamp = (v, min, max) => Math.min(max, Math.max(min, v));

function formatTime(hours) {
  const minute = Math.floor(((hours % 1) * 60) + 0.5);
  const displayHour = ((Math.floor(hours) % 24) + 24) % 24;
  const suffix = displayHour >= 12 ? 'PM' : 'AM';
  const twelveHour = displayHour % 12 || 12;
  return `${twelveHour}:${String(minute).padStart(2, '0')} ${suffix}`;
}

function setMessage(text) {
  gameState.message = text;
  messageBox.textContent = text;
}

function updateHUD() {
  timeLabel.textContent = formatTime(world.time);
  powerLabel.textContent = `${Math.round(world.solarPower)}%`;
  batteryLabel.textContent = `${Math.round(world.battery)}%`;
  statusLabel.textContent = world.gameOver ? (world.winningEnding ? 'Ending reached' : 'Station lost') : (world.flashlightOn ? 'Flashlight active' : 'Darkness');

  const objectives = gameState.endState ? ['Ending: ' + gameState.endState] : [...world.objectives];
  objectiveList.innerHTML = objectives.map((obj, index) => `<li>${obj}</li>`).join('');

  inventoryList.innerHTML = world.inventory.map(item => `<li>${item}</li>`).join('') || '<li>Empty</li>';
}

function addItem(itemName) {
  if (!world.inventory.includes(itemName)) {
    world.inventory.push(itemName);
  }
}

function findNearbyObject() {
  const near = [];
  for (const item of items) {
    if (!item.found && Math.hypot(player.x - item.x, player.y - item.y) < 34) {
      near.push(item);
    }
  }

  if (world.generatorOn && Math.hypot(player.x - stations.fuel.x, player.y - stations.fuel.y) < 42) {
    near.push({ id: 'generator', label: 'Generator', description: 'Keep the power elevated.' });
  }

  if (Math.hypot(player.x - stations.office.x, player.y - stations.office.y) < 42) {
    near.push({ id: 'office', label: 'Office', description: 'Check records and lock the station.' });
  }

  if (Math.hypot(player.x - stations.register.x, player.y - stations.register.y) < 42) {
    near.push({ id: 'counter', label: 'Counter', description: 'The till has a key hidden behind it.' });
  }

  if (Math.hypot(player.x - stations.woods.x, player.y - stations.woods.y) < 54) {
    near.push({ id: 'forest', label: 'Forest edge', description: 'The area beyond the pumps smells of wet iron.' });
  }

  return near;
}

function setNearMessage() {
  const near = findNearbyObject();
  if (near.length) {
    gameState.nearObject = near[0];
    setMessage(`${near[0].label}: ${near[0].description}`);
  } else {
    gameState.nearObject = null;
    setMessage('The station holds its breath.');
  }
}

function findItemById(id) {
  return items.find(item => item.id === id);
}

function pickupItem(item) {
  if (item.found) return;
  item.found = true;
  addItem(item.label);
  setMessage(`You picked up the ${item.label}.`);

  if (item.id === 'battery') {
    world.battery = clamp(world.battery + 20, 0, 100);
  }
  if (item.id === 'fuelCan') {
    gameState.generatorFuel = true;
  }
  if (item.id === 'key') {
    gameState.maintenanceKey = true;
    world.keysFound += 1;
  }
  if (item.id === 'newspaper') {
    setMessage('The paper warns: “No one comes back from the pines after midnight.”');
  }
}

function interact() {
  if (world.gameOver) return;

  const near = findNearbyObject();
  const interactItem = near.find(obj => obj.id && obj.id !== 'forest' && obj.id !== 'office');
  if (interactItem) {
    if (interactItem.id === 'generator') {
      if (gameState.generatorFuel) {
        world.generator = 100;
        gameState.generatorOn = true;
        setMessage('You refill the generator. The station hums back to life.');
      } else {
        setMessage('The generator is dead. You need fuel.');
      }
      return;
    }

    if (interactItem.id === 'counter') {
      if (gameState.maintenanceKey) {
        setMessage('The counter drawer contains emergency supplies: spare batteries and a flashlight lens.');
        world.battery = clamp(world.battery + 15, 0, 100);
      } else {
        setMessage('There is a locked drawer under the counter.');
      }
      return;
    }

    if (interactItem.id === 'office') {
      if (gameState.maintenanceKey) {
        gameState.officeUnlocked = true;
        setMessage('Inside the office, you find a logbook: “Someone keeps the station lit after dark.”');
        world.inventory.push('Station log');
      } else {
        setMessage('The office door is locked. You need a maintenance key.');
      }
      return;
    }

    if (interactItem.id === 'forest') {
      if (gameState.maintenanceKey) {
        world.winningEnding = 'escape';
        triggerEnding('You flee into the woods while the station falls silent behind you.');
      } else {
        setMessage('The forest edge is empty and too dark to trust.');
      }
      return;
    }
  }

  const item = items.find(i => !i.found && Math.hypot(player.x - i.x, player.y - i.y) < 34);
  if (item) {
    pickupItem(item);
    return;
  }

  if (Math.hypot(player.x - stations.register.x, player.y - stations.register.y) < 52) {
    if (!gameState.maintenanceKey) {
      setMessage('You search the register and find a torn maintenance key tag under a bucket.');
      gameState.maintenanceKey = true;
      addItem('Maintenance Key');
      world.keysFound += 1;
    } else {
      setMessage('The register is empty now.');
    }
    return;
  }

  if (Math.hypot(player.x - stations.office.x, player.y - stations.office.y) < 60 && world.inventory.includes('Station log')) {
    triggerEnding('You stay and listen to the logbook. The station answers back.');
    return;
  }

  if (Math.hypot(player.x - stations.woods.x, player.y - stations.woods.y) < 44) {
    setMessage('The pine trees rustle like whispers. Something watches from deeper in the forest.');
    return;
  }

  setMessage('Nothing useful here. Keep moving.');
}

function triggerEnding(text) {
  world.gameOver = true;
  world.winningEnding = world.winningEnding || 'stay';
  setMessage(text);
  statusLabel.textContent = 'Ending reached';
  setTimeout(() => {
    setMessage(`${text} The night ends at 6:00 AM.`);
  }, 1500);
}

function useCamera() {
  if (world.gameOver) return;
  world.camerasOpen = !world.camerasOpen;
  if (world.camerasOpen) {
    gameState.activeCamera = 0;
    setMessage('Security monitors flicker alive. Pump lane, truck bay, and forest road are visible.');
  } else {
    gameState.activeCamera = null;
    setMessage('Camera feed drops back to darkness.');
  }
}

function toggleFlashlight() {
  if (world.gameOver) return;
  world.flashlightOn = !world.flashlightOn;
  setMessage(world.flashlightOn ? 'Flashlight clicks on. The dark tightens around you.' : 'Flashlight goes dark. You feel watched.');
}

function updateWorld(dt) {
  world.time += dt / 3600;
  if (world.time >= 6) {
    if (!world.gameOver) {
      if (world.generator > 0 && world.solarPower > 0) {
        triggerEnding('Sunrise arrives. The station survives the night.');
        world.winningEnding = world.winningEnding || 'survive';
      } else {
        triggerEnding('The station dies before dawn. The forest swallows the last shift.');
        world.winningEnding = 'bad';
      }
    }
    return;
  }

  const powerDrain = 3.2 + (world.flashlightOn ? 4.6 : 0);
  world.generator = clamp(world.generator - powerDrain * dt / 60, 0, 100);
  world.solarPower = clamp(world.solarPower - dt / 32, 0, 100);
  world.battery = clamp(world.battery - (world.flashlightOn ? dt / 100 : 0), 0, 100);

  if (world.flashlightOn && world.battery <= 0) {
    world.flashlightOn = false;
    setMessage('The flashlight dies. You are left with only the station lights.');
  }

  if (world.generator <= 0) {
    world.solarPower = clamp(world.solarPower - dt / 20, 0, 100);
    if (!gameState.customerWarning) {
      setMessage('The backup lights fade. A customer in the lot has not left.');
      gameState.customerWarning = true;
    }
  }

  if (world.generator > 55 && world.time > 1.5) {
    customers[1].active = true;
  }

  if (world.time > 3.4 && !world.seenThreat) {
    world.seenThreat = true;
    setMessage('Something is moving outside the windows. The station is not empty.');
  }

  if (world.time > 4.5 && player.x > 650) {
    setMessage('A figure moves in the rain between the pumps. Keep your distance.');
  }
}

function updatePlayer(dt) {
  let dx = 0;
  let dy = 0;

  if (keys.ArrowUp) dy -= 1;
  if (keys.ArrowDown) dy += 1;
  if (keys.ArrowLeft) dx -= 1;
  if (keys.ArrowRight) dx += 1;

  if (dx || dy) {
    const len = Math.hypot(dx, dy) || 1;
    dx /= len; dy /= len;
    player.x += dx * player.speed * dt;
    player.y += dy * player.speed * dt;
    player.x = clamp(player.x, 50, world.width - 50);
    player.y = clamp(player.y, 36, world.height - 38);
    player.facing.x = dx; player.facing.y = dy;
  }
}

function drawBackground() {
  ctx.fillStyle = '#081010';
  ctx.fillRect(0, 0, world.width, world.height);

  ctx.fillStyle = '#0a1713';
  ctx.fillRect(60, 60, 820, 480);

  ctx.fillStyle = '#2a2f2d';
  ctx.fillRect(100, 210, 170, 110);
  ctx.fillRect(320, 210, 180, 110);
  ctx.fillRect(610, 210, 200, 110);

  ctx.fillStyle = '#7f8c88';
  ctx.fillRect(420, 120, 190, 245);
  ctx.fillRect(90, 120, 120, 90);
  ctx.fillRect(210, 120, 120, 90);
  ctx.fillRect(270, 120, 120, 90);
  ctx.fillRect(680, 120, 120, 90);

  ctx.fillStyle = '#423d2d';
  ctx.fillRect(120, 110, 130, 90);
  ctx.fillRect(210, 110, 130, 90);
  ctx.fillRect(300, 110, 130, 90);
  ctx.fillRect(710, 150, 110, 115);

  ctx.fillStyle = '#2f3536';
  ctx.fillRect(130, 430, 120, 80);
  ctx.fillRect(530, 390, 160, 120);
  ctx.fillRect(710, 420, 160, 120);

  ctx.fillStyle = '#1d2b2a';
  ctx.fillRect(740, 382, 150, 130);

  ctx.fillStyle = '#5a4a2d';
  for (const station of Object.values(stations)) {
    ctx.fillRect(station.x, station.y, station.w, station.h);
  }

  ctx.fillStyle = '#4d3d27';
  ctx.fillRect(250, 430, 180, 50);

  ctx.fillStyle = '#5f5d52';
  ctx.fillRect(630, 430, 60, 90);

  ctx.fillStyle = '#111';
  ctx.fillRect(0, 0, world.width, world.height);

  ctx.fillStyle = 'rgba(200,245,255,0.08)';
  for (let i = 0; i < 60; i++) {
    const x = (i * 133 + (performance.now() * 0.03)) % (world.width + 80) - 40;
    const y = (i * 79 + (performance.now() * 0.02)) % (world.height + 80) - 40;
    ctx.fillRect(x, y, 2, 2);
  }
}

function drawStationLabels() {
  ctx.font = '12px sans-serif';
  ctx.fillStyle = '#d9eefc';
  for (const station of Object.values(stations)) {
    ctx.fillText(station.name, station.x + 6, station.y - 8);
  }
}

function drawItems() {
  for (const item of items) {
    if (item.found) continue;
    ctx.beginPath();
    ctx.fillStyle = item.id === 'battery' ? '#f9d65d' : item.id === 'key' ? '#d6e0ff' : item.id === 'fuelCan' ? '#ff9a59' : '#d8e8ee';
    ctx.arc(item.x, item.y, 8, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawCustomers() {
  for (const customer of customers) {
    if (!customer.active) continue;
    ctx.beginPath();
    ctx.fillStyle = customer.name === 'Watcher' ? '#d5cbff' : '#d7b881';
    ctx.arc(customer.x, customer.y, 10, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawPlayer() {
  ctx.beginPath();
  ctx.fillStyle = '#dfeeff';
  ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
  ctx.fill();

  ctx.beginPath();
  ctx.strokeStyle = '#9ec0dc';
  ctx.moveTo(player.x, player.y);
  ctx.lineTo(player.x + player.facing.x * 18, player.y + player.facing.y * 18);
  ctx.stroke();
}

function drawCameraOverlay() {
  if (!world.camerasOpen) return;
  ctx.fillStyle = 'rgba(12, 19, 22, 0.72)';
  ctx.fillRect(0, 0, world.width, world.height);
  ctx.fillStyle = 'rgba(135, 193, 255, 0.12)';
  for (const cam of cameraViews) {
    ctx.fillRect(cam.x, cam.y, cam.w, cam.h);
    ctx.strokeStyle = '#d6ebff';
    ctx.strokeRect(cam.x, cam.y, cam.w, cam.h);
    ctx.fillStyle = '#d6ebff';
    ctx.font = '12px sans-serif';
    ctx.fillText(cam.name, cam.x + 10, cam.y + 20);
  }
  ctx.fillStyle = '#a5d7ff';
  ctx.font = '14px sans-serif';
  ctx.fillText('Cameras: live feed', 40, 30);
}

function drawFog() {
  const alpha = world.flashlightOn ? 0.48 : 0.78;
  ctx.fillStyle = `rgba(0, 0, 0, ${alpha})`;
  ctx.fillRect(0, 0, world.width, world.height);

  if (world.flashlightOn) {
    const grd = ctx.createRadialGradient(player.x, player.y, 10, player.x, player.y, 160);
    grd.addColorStop(0, 'rgba(255,255,200,0.9)');
    grd.addColorStop(0.25, 'rgba(255,250,200,0.35)');
    grd.addColorStop(1, 'rgba(10, 17, 22, 0.03)');
    ctx.fillStyle = grd;
    ctx.fillRect(player.x - 180, player.y - 180, 360, 360);
  }
}

function render() {
  drawBackground();
  drawStationLabels();
  drawItems();
  drawCustomers();
  drawPlayer();
  drawCameraOverlay();
  drawFog();
}

let lastTime = 0;
function gameLoop(ts) {
  const dt = Math.min(0.033, (ts - lastTime) / 1000 || 0.016);
  lastTime = ts;

  if (!world.gameOver) {
    updatePlayer(dt);
    updateWorld(dt);
    setNearMessage();
  }

  updateHUD();
  render();
  requestAnimationFrame(gameLoop);
}

function handleKey(e) {
  if (e.key in keys) {
    keys[e.key] = true;
    e.preventDefault();
  }
  if (e.key === 'e' || e.key === 'E') interact();
  if (e.key === 'c' || e.key === 'C') useCamera();
  if (e.key === 'f' || e.key === 'F') toggleFlashlight();
}

function handleKeyUp(e) {
  if (e.key in keys) keys[e.key] = false;
}

document.addEventListener('keydown', handleKey);
document.addEventListener('keyup', handleKeyUp);
interactButton.addEventListener('click', interact);
cameraButton.addEventListener('click', useCamera);
flashlightButton.addEventListener('click', toggleFlashlight);

Array.from(document.querySelectorAll('.move-btn')).forEach(button => {
  const key = button.dataset.key;
  const press = (event) => {
    event.preventDefault();
    keys[key] = true;
  };
  const release = (event) => {
    event.preventDefault();
    keys[key] = false;
  };
  button.addEventListener('pointerdown', press);
  button.addEventListener('pointerup', release);
  button.addEventListener('pointerleave', release);
  button.addEventListener('pointercancel', release);
});

setMessage('Your shift begins. Keep the station alive and find the truth in the dark.');
updateHUD();
requestAnimationFrame(gameLoop);

